package com.bct.ngtpa.apiservice.application.service.auth.login.context;
import com.bct.ngtpa.apiservice.application.dto.auth.login.otp.*;import com.bct.ngtpa.apiservice.application.dto.auth.login.preauth.*;import com.bct.ngtpa.apiservice.application.dto.session.authflow.*;import com.bct.ngtpa.apiservice.application.port.out.*;import com.bct.ngtpa.apiservice.application.usecase.session.authflow.*;import java.time.*;import java.util.*;import reactor.core.publisher.Mono;
public final class DefaultLoginProtectedAuthFlowContextLoader implements LoginProtectedAuthFlowContextLoader {
 private final AuthFlowSessionLifecycleService lifecycle;private final AuthFlowSessionCsrfService csrf;private final LoginPreAuthContextProtectorPort protector;private final Clock clock;
 public DefaultLoginProtectedAuthFlowContextLoader(AuthFlowSessionLifecycleService lifecycle,AuthFlowSessionCsrfService csrf,LoginPreAuthContextProtectorPort protector,Clock clock){this.lifecycle=Objects.requireNonNull(lifecycle);this.csrf=Objects.requireNonNull(csrf);this.protector=Objects.requireNonNull(protector);this.clock=Objects.requireNonNull(clock);}
 public Mono<LoginProtectedAuthFlowContextResult> load(LoginProtectedAuthFlowContextCommand c){Instant now=clock.instant();var id=new AuthFlowSessionId(c.authFlowSessionId());return csrf.validateForSession(new ValidateAuthFlowSessionCsrfCommand(id,c.csrfToken(),now,c.origin(),c.referer(),List.of(),c.correlationId())).flatMap(v->{if(!v.valid())return Mono.just(LoginProtectedAuthFlowContextResult.invalid(map(v.status())));return lifecycle.load(new LoadAuthFlowSessionCommand(id,c.correlationId())).map(o->validate(o,now));}).onErrorReturn(LoginProtectedAuthFlowContextResult.invalid(LoginProtectedAuthFlowContextStatus.CSRF_INVALID));}
 private LoginProtectedAuthFlowContextResult validate(Optional<AuthFlowSession> o,Instant now){if(o.isEmpty())return invalid(LoginProtectedAuthFlowContextStatus.MISSING_SESSION);var s=o.get();if(s.isExpired(now)||s.isTerminal())return invalid(LoginProtectedAuthFlowContextStatus.EXPIRED_OR_TERMINAL_SESSION);if(s.scenario()!=AuthFlowScenario.LOGIN)return invalid(LoginProtectedAuthFlowContextStatus.WRONG_SCENARIO);if(s.status()!=AuthFlowStatus.STARTED)return invalid(LoginProtectedAuthFlowContextStatus.INVALID_STATUS);Map<String,String>a=s.data()==null?Map.of():s.data().attributes();String v=a.get("loginContext.keyVersion"),alg=a.get("loginContext.algorithm"),iv=a.get("loginContext.iv"),ct=a.get("loginContext.ciphertext");if(blank(v)||blank(alg)||blank(iv)||blank(ct))return invalid(LoginProtectedAuthFlowContextStatus.MISSING_CONTEXT);try{return LoginProtectedAuthFlowContextResult.valid(protector.unprotect(new LoginPreAuthEncryptedContext(v,alg,iv,ct)));}catch(RuntimeException e){return invalid(LoginProtectedAuthFlowContextStatus.CONTEXT_DECRYPTION_FAILED);}}
 private LoginProtectedAuthFlowContextStatus map(AuthFlowSessionCsrfValidationStatus s){if(s==AuthFlowSessionCsrfValidationStatus.SESSION_MISSING)return LoginProtectedAuthFlowContextStatus.MISSING_SESSION;if(s==AuthFlowSessionCsrfValidationStatus.SESSION_EXPIRED||s==AuthFlowSessionCsrfValidationStatus.SESSION_NOT_USABLE)return LoginProtectedAuthFlowContextStatus.EXPIRED_OR_TERMINAL_SESSION;if(s==AuthFlowSessionCsrfValidationStatus.ORIGIN_REFERER_INVALID)return LoginProtectedAuthFlowContextStatus.ORIGIN_REFERER_INVALID;return LoginProtectedAuthFlowContextStatus.CSRF_INVALID;}
 private LoginProtectedAuthFlowContextResult invalid(LoginProtectedAuthFlowContextStatus s){return LoginProtectedAuthFlowContextResult.invalid(s);}private boolean blank(String v){return v==null||v.isBlank();}
}
